import React, { useEffect, useState } from 'react';
import api from '../services/api';
import ProfCard from '../components/ProfCard';
import ProfModal from './ProfModal';

const MATIERES = ['Mathématiques','Physique','Chimie','Français','Anglais','Arabe','SVT','Histoire-Géo','Informatique','Philosophie'];
const VILLES = ['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana','Ben Arous','Mahdia'];

export default function Profs() {
  const [profs, setProfs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterMat, setFilterMat] = useState('');
  const [filterVille, setFilterVille] = useState('');
  const [filterMax, setFilterMax] = useState('');
  const [sort, setSort] = useState('note');
  const [selectedProf, setSelectedProf] = useState(null);

  useEffect(() => {
    const params = new URLSearchParams();
    if (filterMat) params.set('matiere', filterMat);
    if (filterVille) params.set('ville', filterVille);
    if (filterMax) params.set('tarif_max', filterMax);
    api.get(`/api/professeurs/?${params}`).then(r => { setProfs(r.data); setLoading(false); }).catch(() => setLoading(false));
  }, [filterMat, filterVille, filterMax]);

  const filtered = profs
    .filter(p => !search || (p.user_nom || '').toLowerCase().includes(search.toLowerCase()) || (p.matieres?.[0] || '').toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => sort === 'note' ? (parseFloat(b.note_moyenne) - parseFloat(a.note_moyenne)) : (parseFloat(a.tarif) - parseFloat(b.tarif)));

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
        <div>
          <div style={{ fontFamily: 'Syne', fontSize: '1.2rem', fontWeight: 700 }}>👨‍🏫 Nos Professeurs</div>
          <div style={{ fontSize: '.85rem', color: 'var(--text2)' }}>{filtered.length} professeur(s) disponible(s)</div>
        </div>
      </div>

      {/* Filters */}
      <div style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 16, padding: 20, marginBottom: 24, display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 12 }}>
        <input style={inp} placeholder="🔍 Rechercher..." value={search} onChange={e => setSearch(e.target.value)} />
        <select style={inp} value={filterMat} onChange={e => setFilterMat(e.target.value)}>
          <option value="">Toutes matières</option>
          {MATIERES.map(m => <option key={m}>{m}</option>)}
        </select>
        <select style={inp} value={filterVille} onChange={e => setFilterVille(e.target.value)}>
          <option value="">Toutes villes</option>
          {VILLES.map(v => <option key={v}>{v}</option>)}
        </select>
        <select style={inp} value={sort} onChange={e => setSort(e.target.value)}>
          <option value="note">Trier: Meilleure note</option>
          <option value="tarif">Trier: Moins cher</option>
        </select>
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: 60, color: 'var(--text2)' }}>⏳ Chargement...</div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 20 }}>
          {filtered.map(p => <ProfCard key={p.id} prof={p} onView={setSelectedProf} />)}
        </div>
      )}

      {filtered.length === 0 && !loading && (
        <div style={{ textAlign: 'center', padding: 60, color: 'var(--text2)' }}>Aucun professeur trouvé.</div>
      )}

      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}
    </div>
  );
}
